        let fixtures: &[(&str, &str)] = &[
            (
                "Padded standard base64 data.",
                "{\n  \"complete\": true,\n  \"contentType\": \"text/html\",\n  \"data\": \"PGh0bWw+PC9odG1sPgo=\",\n  \"etag\": \"3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b8a55\",\n  \"offset\": 0,\n  \"path\": \"/a.html\",\n  \"sizeBytes\": 14\n}",
            ),
            (
                "Response without `complete` — the caller must know whether to ask for the next range.",
                "{\n  \"contentType\": \"text/html\",\n  \"data\": \"PGh0bWw-PC9odG1sPgo\",\n  \"etag\": \"3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b8a55\",\n  \"offset\": 0,\n  \"path\": \"/a.html\",\n  \"sizeBytes\": 14\n}",
            ),
        ];
